import express from "express";
import { fileURLToPath } from "node:url";
import {
  connectDB,
  getAllProducts,
  findProductsByCategory,
  findLowStockProducts,
  getThreeCostliestProducts,
  addProduct,
} from "./database.js";

const app = express();
const PORT = 3000;

app.use(express.json());
app.use(express.static(fileURLToPath(new URL("./public", import.meta.url))));

function sendList(res, data, functionName) {
  if (!Array.isArray(data)) {
    return res.status(500).json({
      error: `${functionName}() did not return a list from the database. Complete it in database.js.`,
    });
  }
  res.json(data);
}

app.get("/api/products", async (req, res) => {
  try {
    sendList(res, await getAllProducts(), "getAllProducts");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/products/search", async (req, res) => {
  try {
    sendList(res, await findProductsByCategory(req.query.category), "findProductsByCategory");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/products/filter", async (req, res) => {
  const maxStock = Number(req.query.maxStock);
  if (Number.isNaN(maxStock)) {
    return res.status(400).json({ error: "Please enter a number." });
  }
  try {
    sendList(res, await findLowStockProducts(maxStock), "findLowStockProducts");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/products/top", async (req, res) => {
  try {
    sendList(res, await getThreeCostliestProducts(), "getThreeCostliestProducts");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post("/api/products", async (req, res) => {
  try {
    const saved = await addProduct(req.body);
    if (!saved) {
      return res.status(500).json({
        error: "addProduct() did not return the saved product. Complete it in database.js.",
      });
    }
    res.status(201).json(saved);
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

try {
  await connectDB();
} catch (err) {
  console.log("Could not connect to MongoDB:", err.message);
}

app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
